mapper.select:
SELECT s.scope_id FROM w18_module_install_scope s
  JOIN w18_module_install_reservation r ON r.reservation_key = s.reservation_key
WHERE r.license_key = #{licenseKey}
  AND (r.state = 'CONSUMED' OR (r.state = 'RESERVED' AND r.expires_at > #{now}))
  AND s.scope_kind = #{kind}
ORDER BY s.scope_id FOR UPDATE
